 const string Flag="ValoriaReferenceClean.PlayProbe";static double entered;static int errors;
 static ValoriaReferenceCleanPlayProbe(){EditorApplication.playModeStateChanged+=Changed;UnityEngine.Application.logMessageReceived+=Log;}
 static void Log(string message,string stack,LogType type){if(SessionState.GetBool(Flag,false)&&(type==LogType.Exception||type==LogType.Error))errors++;}
 static string Fingerprint(string path){if(!File.Exists(path))return "ABSENT";using(var hash=System.Security.Cryptography.SHA256.Create())return BitConverter.ToString(hash.ComputeHash(File.ReadAllBytes(path)));}
 public static void Build(){SessionState.SetString(Flag+"CanonicalSave",Fingerprint(Eldoria.Presentation.SliceBoot.SavePath));SessionState.SetBool(Flag,true);SessionState.SetInt(Flag+"Result",0);EditorSceneManager.OpenScene("Assets/Eldoria/ArtTests/ValoriaReferenceClean/Valoria_Reference_Clean.unity",OpenSceneMode.Single);EditorApplication.EnterPlaymode();}
 static void Changed(PlayModeStateChange state){if(!SessionState.GetBool(Flag,false))return;if(state==PlayModeStateChange.EnteredPlayMode){entered=EditorApplication.timeSinceStartup;errors=0;EditorApplication.update+=Tick;}if(state==PlayModeStateChange.EnteredEditMode){bool pass=SessionState.GetInt(Flag+"Result",0)==1;SessionState.SetBool(Flag,false);if(pass){try{var root="Assets/Eldoria/ArtTests/ValoriaReferenceClean";var scene=root+"/Valoria_Reference_Clean.unity";var inputs=new[]{"Assets/Eldoria/Scripts/Presentation/SliceBoot.cs",scene,root+"/Prefabs/Bastion_I.prefab",root+"/Prefabs/FortifiedGate.prefab",root+"/Prefabs/MedievalBridge.prefab",root+"/Prefabs/BuildablePlots.prefab",root+"/Prefabs/Ruins.prefab",root+"/Prefabs/Paths.prefab"};var deps=AssetDatabase.GetDependencies(inputs,true).Where(p=>p.StartsWith("Assets/")).Distinct().ToArray();string package="../docs/evidence/valoria-reference-clean/Valoria_Reference_Clean.unitypackage";AssetDatabase.ExportPackage(deps,package,ExportPackageOptions.Default);if(new FileInfo(package).Length>80L*1024*1024)File.Delete(package);var backup="../docs/evidence/valoria-reference-clean/Valoria_Reference_Clean.blend1";if(File.Exists(backup))File.Delete(backup);}catch(Exception e){Debug.LogWarning("Optional package: "+e.Message);}}Debug.Log(pass?"VALORIA_REFERENCE_CLEAN_PLAY_COMPLETE":"VALORIA_REFERENCE_CLEAN_PLAY_FAILED");EditorApplication.Exit(pass?0:1);}}
 [Serializable]class RenderConsistencyReport{public string editor_sha,play_sha,note;public int compared_pixels,changed_pixels,channel_threshold;public float changed_fraction;public bool consistent;}
 static void CheckRenderConsistency(){string path="../docs/evidence/valoria-reference-clean/";var a=new Texture2D(2,2);var b=new Texture2D(2,2);try{a.LoadImage(File.ReadAllBytes(path+"D-final.png"));b.LoadImage(File.ReadAllBytes(path+"playmode-home.png"));if(a.width!=b.width||a.height!=b.height)throw new Exception("Editor/Play camera capture dimensions differ");var aa=a.GetPixels32();var bb=b.GetPixels32();int changed=0,total=0;for(int y=350;y<a.height-40;y++)for(int x=40;x<a.width-40;x++){int i=y*a.width+x;total++;if(Math.Abs(aa[i].r-bb[i].r)>24||Math.Abs(aa[i].g-bb[i].g)>24||Math.Abs(aa[i].b-bb[i].b)>24)changed++;}float fraction=changed/(float)total;File.WriteAllText(path+"editor-play-consistency.json",JsonUtility.ToJson(new RenderConsistencyReport{editor_sha=Fingerprint(path+"D-final.png"),play_sha=Fingerprint(path+"playmode-home.png"),compared_pixels=total,changed_pixels=changed,channel_threshold=24,changed_fraction=fraction,consistent=fraction<.04f,note="Same native camera; upper field ROI excludes animated river. Consistency gate only, never an artistic approval."},true));if(fraction>=.04f)throw new Exception("Actual PlayMode render differs materially from the authored editor scene: "+fraction);}finally{UnityEngine.Object.DestroyImmediate(a);UnityEngine.Object.DestroyImmediate(b);}}
 static double CameraReadbackProbe(Camera cam){var prior=cam.targetTexture;var active=RenderTexture.active;var target=new RenderTexture(960,540,24);var pixels=new Texture2D(960,540,TextureFormat.RGB24,false);try{cam.targetTexture=target;cam.Render();var watch=System.Diagnostics.Stopwatch.StartNew();for(int i=0;i<8;i++){cam.Render();RenderTexture.active=target;pixels.ReadPixels(new Rect(0,0,960,540),0,0,false);}watch.Stop();return watch.Elapsed.TotalMilliseconds/8;}finally{cam.targetTexture=prior;RenderTexture.active=active;target.Release();UnityEngine.Object.DestroyImmediate(target);UnityEngine.Object.DestroyImmediate(pixels);}}
 static void Tick(){if(EditorApplication.timeSinceStartup-entered<3)return;EditorApplication.update-=Tick;
 try {
 var interaction=UnityEngine.Object.FindFirstObjectByType<ValoriaReferenceCleanInteraction>();if(!interaction||!interaction.isActiveAndEnabled||!UnityEngine.Application.isPlaying)throw new Exception("Live PlayMode interaction missing");
 bool saveUntouched=Fingerprint(Eldoria.Presentation.SliceBoot.SavePath)==SessionState.GetString(Flag+"CanonicalSave","");if(!saveUntouched)throw new Exception("Canonical save changed");var cam=interaction.playerCamera;Physics.SyncTransforms();if(UnityEngine.Object.FindObjectsByType<Eldoria.Presentation.SlicePresenter>(FindObjectsSortMode.None).Length!=0||GameObject.Find("Eldoria composition root")!=null||GameObject.Find("Isometric camera")!=null)throw new Exception("Legacy auto-bootstrap contaminated the independent scene");int cameraCount=UnityEngine.Object.FindObjectsByType<Camera>(FindObjectsSortMode.None).Count(c=>c.enabled);if(cameraCount!=1)throw new Exception("Unexpected active scene cameras: "+cameraCount);int count=0;
 foreach(var box in UnityEngine.Object.FindObjectsByType<BoxCollider>(FindObjectsSortMode.None).Where(c=>c.gameObject.layer==8)){
 var point=cam.WorldToScreenPoint(box.bounds.center);if(!Physics.Raycast(cam.ScreenPointToRay(point),out var hit,500,1<<8)||hit.collider!=box)throw new Exception("PlayMode ray selection: "+box.name);interaction.Select(hit.collider.name);if(box.name.StartsWith("Parcela")&&interaction.plot<1)throw new Exception("PlayMode parcel state missing");count++;
 }
 var routeFailures=new List<string>();int routePass=0,routeTotal=0;float lastHeight=0,maxStep=0;for(float z=-70;z<=25;z+=1){routeTotal++;if(Physics.Raycast(new Vector3(ValoriaReferenceCleanArtBuilder.RoadX(z),20,z),Vector3.down,out var h,40,~(1<<8),QueryTriggerInteraction.Ignore)&&h.point.y>-.1f&&h.point.y<1.2f){routePass++;if(routeTotal>1)maxStep=Mathf.Max(maxStep,Mathf.Abs(h.point.y-lastHeight));lastHeight=h.point.y;}else routeFailures.Add(z+":"+(h.collider?h.collider.name+"@"+h.point.y:"no surface"));}
 int stairsPass=0;for(int i=0;i<6;i++){if(Physics.Raycast(new Vector3(0,20,25.75f+i*.46f),Vector3.down,out var h,40,~(1<<8),QueryTriggerInteraction.Ignore)&&Mathf.Abs(h.point.y-(.57f+i*.19f))<.12f)stairsPass++;}
 if(routePass!=routeTotal||stairsPass!=6){foreach(var terrainCol in UnityEngine.Object.FindObjectsByType<TerrainCollider>(FindObjectsSortMode.None)){var data=terrainCol.terrainData;bool direct=terrainCol.Raycast(new Ray(new Vector3(0,20,14),Vector3.down),out var terrainHit,50);Debug.Log("TERRAIN_ROUTE_DIAGNOSTIC layer="+terrainCol.gameObject.layer+" enabled="+terrainCol.enabled+" bounds="+terrainCol.bounds+" data="+data+" solidCentre="+(data?data.GetHoles(128,128,1,1)[0,0]:false)+" directHit="+direct+" hit="+terrainHit.point);}}if(routePass!=routeTotal||stairsPass!=6)throw new Exception("Physical route or stairs fail: "+routePass+"/"+routeTotal+", stairs="+stairsPass+"; "+string.Join(";",routeFailures));
 // Actual PlayMode static batching previously corrupted a 77k-vertex multi-material mesh.
 // Inspect the evaluated runtime buffers, not just the exported GLB or editor image.
 int checkedMeshes=0;var seenMeshes=new HashSet<Mesh>();foreach(var filter in UnityEngine.Object.FindObjectsByType<MeshFilter>(FindObjectsSortMode.None)){var mesh=filter.sharedMesh;if(!mesh||!mesh.isReadable||!seenMeshes.Add(mesh))continue;var points=mesh.vertices;checkedMeshes++;for(int sub=0;sub<mesh.subMeshCount;sub++){var ii=mesh.GetIndices(sub,true);for(int i=0;i+2<ii.Length;i+=3){var a=points[ii[i]];var b=points[ii[i+1]];var c=points[ii[i+2]];if((a-b).sqrMagnitude>2500||(b-c).sqrMagnitude>2500||(a-c).sqrMagnitude>2500)throw new Exception("Runtime mesh contains scene-spanning triangle: "+mesh.name);}}}
 float before=cam.orthographicSize;cam.orthographicSize=24;ValoriaReferenceCleanBuilder.Capture(cam,"../docs/evidence/valoria-reference-clean/playmode-zoom.png",1448,1086);cam.orthographicSize=before;
 var origin=cam.transform.position;cam.transform.position+=Vector3.right*6;ValoriaReferenceCleanBuilder.Capture(cam,"../docs/evidence/valoria-reference-clean/playmode-pan.png",1448,1086);cam.transform.position=origin;interaction.Select("Bastión I");
 ValoriaReferenceCleanBuilder.Capture(cam,"../docs/evidence/valoria-reference-clean/playmode-home.png",1448,1086);CheckRenderConsistency();
 var textures=new HashSet<Texture>();var rendered=UnityEngine.Object.FindObjectsByType<Renderer>(FindObjectsSortMode.None);foreach(var renderer in rendered)foreach(var material in renderer.sharedMaterials){if(!material)continue;foreach(var key in material.GetTexturePropertyNames()){var texture=material.GetTexture(key);if(texture)textures.Add(texture);}}foreach(var terrain in UnityEngine.Object.FindObjectsByType<Terrain>(FindObjectsSortMode.None))foreach(var layer in terrain.terrainData.terrainLayers){if(layer.diffuseTexture)textures.Add(layer.diffuseTexture);if(layer.normalMapTexture)textures.Add(layer.normalMapTexture);}long textureBytes=textures.Sum(t=>UnityEngine.Profiling.Profiler.GetRuntimeMemorySizeLong(t));int meshTriangles=0;foreach(var filter in UnityEngine.Object.FindObjectsByType<MeshFilter>(FindObjectsSortMode.None)){var mesh=filter.sharedMesh;if(!mesh)continue;for(int sub=0;sub<mesh.subMeshCount;sub++)meshTriangles+=(int)mesh.GetIndexCount(sub)/3;}double readbackMs=CameraReadbackProbe(cam);
 File.WriteAllText("../docs/evidence/valoria-reference-clean/playmode.json",JsonUtility.ToJson(new Report{runtime_meshes_checked=checkedMeshes,playmode=true,canonical_save_untouched=saveUntouched,active_scene_cameras=cameraCount,legacy_boot_present=false,selectable_targets=count,route_probes=routeTotal,route_passes=routePass,stairs_passes=stairsPass,max_route_step=maxStep,zoom_camera_changed=true,pan_camera_changed=true,exceptions=errors,editor_batches=UnityStats.batches,editor_setpass_calls=UnityStats.setPassCalls,editor_triangles=UnityStats.triangles,physical_mobile_tested=false,scene_mesh_triangles=meshTriangles,scene_renderers=rendered.Length,scene_material_slots=rendered.Sum(r=>r.sharedMaterials.Length),scene_texture_native_bytes=textureBytes,camera_render_readback_ms_960x540=readbackMs,performance_note="Native Windows camera render plus GPU readback wall time; not mobile FPS. UnityStats frame counters unavailable in batch mode."},true));
 if(count!=5||errors!=0)throw new Exception("Live probes fail: targets="+count+", errors="+errors);SessionState.SetInt(Flag+"Result",1);
 }catch(Exception e){Debug.LogException(e);SessionState.SetInt(Flag+"Result",0);}EditorApplication.ExitPlaymode();
 }
